        private final String eventId;
        private final LocalDateTime timestamp;
        private final EventType type;
        private final Severity severity;
        private final String source;
        private final String user;
        private final String ipAddress;
        private final String description;
        private final Map<String, String> metadata;

        public SecurityEvent(EventType type, Severity severity, String source,
                           String user, String ipAddress, String description) {
            this.eventId = UUID.randomUUID().toString();
            this.timestamp = LocalDateTime.now();
            this.type = type;
            this.severity = severity;
            this.source = source;
            this.user = user;
            this.ipAddress = ipAddress;
            this.description = description;
            this.metadata = new HashMap<>();
        }

        // Getters
        public String getEventId() { return eventId; }
        public LocalDateTime getTimestamp() { return timestamp; }
        public EventType getType() { return type; }
        public Severity getSeverity() { return severity; }
        public String getSource() { return source; }
        public String getUser() { return user; }
        public String getIpAddress() { return ipAddress; }
        public String getDescription() { return description; }
        public Map<String, String> getMetadata() { return metadata; }

        public void addMetadata(String key, String value) {
            metadata.put(key, value);
        }

        @Override
        public String toString() {
            return String.format("[%s] %s | %s | %s | %s | %s | %s",
                timestamp.format(DateTimeFormatter.ISO_LOCAL_DATE_TIME),
                severity, type, source, user, ipAddress, description);
        }
    }

    public static class SecurityLogger {
        private final List<SecurityEvent> events;
        private final String logFilePath;
        private final Severity minimumSeverity;

        public SecurityLogger(String logFilePath, Severity minimumSeverity) {
            this.events = Collections.synchronizedList(new ArrayList<>());
            this.logFilePath = logFilePath;
            this.minimumSeverity = minimumSeverity;
        }

        public void logEvent(SecurityEvent event) {
            if (event.getSeverity().ordinal() >= minimumSeverity.ordinal()) {
                events.add(event);
                writeToFile(event);
                writeToConsole(event);
            }
        }

        private void writeToFile(SecurityEvent event) {
            try (PrintWriter writer = new PrintWriter(new FileWriter(logFilePath, true))) {
                writer.println(event.toString());
                if (!event.getMetadata().isEmpty()) {
                    writer.println("  Metadata: " + event.getMetadata());
                }
            } catch (IOException e) {
                System.err.println("Failed to write to log file: " + e.getMessage());
            }
        }

        private void writeToConsole(SecurityEvent event) {
            System.out.println(event);
        }

        public List<SecurityEvent> getEvents() {
            return new ArrayList<>(events);
        }

        public List<SecurityEvent> getEventsBySeverity(Severity severity) {
            return events.stream()
                .filter(e -> e.getSeverity() == severity)
                .collect(Collectors.toList());
        }

        public List<SecurityEvent> getEventsByType(EventType type) {
            return events.stream()
