            this.logger = logger;
            this.failedAttemptsByIp = new ConcurrentHashMap<>();
            this.failedAttemptsByUser = new ConcurrentHashMap<>();
            this.bruteForceThreshold = bruteForceThreshold;
        }

        public void analyzeEvent(SecurityEvent event) {
            if (event.getType() == EventType.LOGIN_FAILURE) {
                String ip = event.getIpAddress();
                String user = event.getUser();

                int ipAttempts = failedAttemptsByIp.merge(ip, 1, Integer::sum);
                int userAttempts = failedAttemptsByUser.merge(user, 1, Integer::sum);

                if (ipAttempts >= bruteForceThreshold) {
                    SecurityEvent alert = new SecurityEvent(
                        EventType.BRUTE_FORCE_DETECTED,
                        Severity.CRITICAL,
                        "SecurityAnalyzer",
                        user,
                        ip,
                        "Brute force attack detected from IP: " + ip +
                        " (" + ipAttempts + " failed attempts)"
                    );
