                    SecurityEvent alert = new SecurityEvent(
                        EventType.BRUTE_FORCE_DETECTED,
                        Severity.CRITICAL,
                        "SecurityAnalyzer",
                        user,
                        ip,
                        "Brute force attack detected on user: " + user +
                        " (" + userAttempts + " failed attempts)"
                    );
                    alert.addMetadata("failedAttempts", String.valueOf(userAttempts));
                    logger.logEvent(alert);
                }
