                .map(SecurityEvent::getUser)
                .collect(Collectors.toSet());

            report.put("totalEvents", totalEvents);
            report.put("criticalEvents", criticalEvents);
            report.put("errorEvents", errorEvents);
            report.put("warningEvents", warningEvents);
            report.put("eventsByType", eventsByType);
            report.put("uniqueIpAddresses", uniqueIps.size());
            report.put("uniqueUsers", uniqueUsers.size());
            report.put("suspiciousIps", new ArrayList<>(failedAttemptsByIp.keySet()));
            report.put("reportGeneratedAt", LocalDateTime.now());

            return report;
        }

