                    // Check if events are within short time window
                    ipEvents.sort(Comparator.comparing(SecurityEvent::getTimestamp));
                    LocalDateTime first = ipEvents.get(0).getTimestamp();
                    LocalDateTime last = ipEvents.get(ipEvents.size() - 1).getTimestamp();

                    if (java.time.Duration.between(first, last).getSeconds() < 60) {
                        SecurityEvent anomaly = new SecurityEvent(
                            EventType.NETWORK_CONNECTION,
                            Severity.WARNING,
                            "SecurityAnalyzer",
                            "system",
                            entry.getKey(),
                            "Rapid activity detected from IP: " + entry.getKey() +
                            " (" + ipEvents.size() + " events in < 60 seconds)"
                        );
                        anomalies.add(anomaly);
                    }
                }
            }

            return anomalies;
        }
    }

